CREATE TABLE morrow.hiring_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES morrow.users,outcome text NOT NULL CHECK(outcome IN ('advance','discuss','decline')),evidence text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,application_id) REFERENCES morrow.applications(org_id,id));
CREATE TABLE morrow.offer_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,offer_id uuid NOT NULL REFERENCES morrow.offers,version integer NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(offer_id,version));
CREATE FUNCTION morrow.capture_offer_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO morrow.offer_versions(org_id,offer_id,version,snapshot) VALUES(NEW.org_id,NEW.id,NEW.version,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER offer_version_capture AFTER INSERT OR UPDATE ON morrow.offers FOR EACH ROW EXECUTE FUNCTION morrow.capture_offer_version();
INSERT INTO morrow.offer_versions(org_id,offer_id,version,snapshot) SELECT org_id,id,version,to_jsonb(o) FROM morrow.offers o;
CREATE TABLE morrow.message_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,name text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,name));
CREATE TABLE morrow.notification_preferences(org_id uuid NOT NULL REFERENCES morrow.organizations,user_id uuid NOT NULL REFERENCES morrow.users,show_tasks boolean NOT NULL DEFAULT true,show_feedback boolean NOT NULL DEFAULT true,PRIMARY KEY(org_id,user_id));
